// Minimal TTL decision helper
function ttlForTenant(baseTTL, ckne) {
  const health = ckne?.health ?? 1;
  const factor = Math.max(0, Math.min(1, health));
  const ttl = Math.round(baseTTL * (1 - (1 - factor) * 0.5));
  return Math.max(30, Math.min(3600, ttl));
}
```

